def matches(pattern, path):
    """True when the whole path matches the glob pattern. See TASK.md."""

    # Validate pattern
    _validate_pattern(pattern)

    # Split by /
    pattern_segments = pattern.split('/')
    path_segments = path.split('/')

    # Match
    return _match_segments(pattern_segments, path_segments)


def _validate_pattern(pattern):
    """Check for errors in the pattern."""
    if pattern and pattern[-1] == '\\':
        raise ValueError("Trailing backslash")

    i = 0
    while i < len(pattern):
        if pattern[i] == '\\':
            i += 2
        elif pattern[i] == '[':
            i, _, _ = _parse_class(pattern, i)
        else:
            i += 1


def _match_segments(pattern_segments, path_segments):
    """Match pattern segments against path segments."""
    return _match_segs_recursive(pattern_segments, path_segments, 0, 0)


def _match_segs_recursive(pattern_segs, path_segs, p_idx, ps_idx):
    """Recursively match pattern segments against path segments."""

    if p_idx == len(pattern_segs) and ps_idx == len(path_segs):
        return True

    if p_idx == len(pattern_segs):
        return False

    if ps_idx == len(path_segs):
        for i in range(p_idx, len(pattern_segs)):
            if pattern_segs[i] != '**':
                return False
        return True

    pattern_seg = pattern_segs[p_idx]

    if pattern_seg == '**':
        if _match_segs_recursive(pattern_segs, path_segs, p_idx + 1, ps_idx):
            return True
        for i in range(ps_idx + 1, len(path_segs) + 1):
            if _match_segs_recursive(pattern_segs, path_segs, p_idx + 1, i):
                return True
        return False
    else:
        if _match_segment(pattern_seg, path_segs[ps_idx]):
            return _match_segs_recursive(pattern_segs, path_segs, p_idx + 1, ps_idx + 1)
        else:
            return False


def _match_segment(pattern, text):
    """Match a pattern segment against a text segment (no /)."""
    return _match_text(pattern, text, 0, 0)


def _match_text(pattern, text, p_idx, t_idx):
    """Recursively match pattern against text."""

    if p_idx == len(pattern) and t_idx == len(text):
        return True

    if p_idx == len(pattern):
        return False

    if pattern[p_idx] == '\\':
        if t_idx >= len(text):
            return False
        if pattern[p_idx + 1] != text[t_idx]:
            return False
        return _match_text(pattern, text, p_idx + 2, t_idx + 1)

    if pattern[p_idx] == '?':
        if t_idx >= len(text):
            return False
        return _match_text(pattern, text, p_idx + 1, t_idx + 1)

    if pattern[p_idx] == '*':
        if p_idx + 1 < len(pattern) and pattern[p_idx + 1] == '*':
            p_idx += 1

        if _match_text(pattern, text, p_idx + 1, t_idx):
            return True
        for i in range(t_idx, len(text)):
            if _match_text(pattern, text, p_idx + 1, i + 1):
                return True
        return False

    if pattern[p_idx] == '[':
        if t_idx >= len(text):
            return False

        p_idx, negate, char_set = _parse_class(pattern, p_idx)

        if negate:
            if text[t_idx] in char_set:
                return False
        else:
            if text[t_idx] not in char_set:
                return False

        return _match_text(pattern, text, p_idx, t_idx + 1)

    if t_idx >= len(text):
        return False
    if pattern[p_idx] != text[t_idx]:
        return False

    return _match_text(pattern, text, p_idx + 1, t_idx + 1)


def _parse_class(pattern, start_idx):
    """Parse a character class and return (end_idx, negate, char_set)."""

    p_idx = start_idx + 1

    negate = False
    if p_idx < len(pattern) and pattern[p_idx] == '!':
        negate = True
        p_idx += 1

    char_set = set()
    last_added = None

    if p_idx < len(pattern) and pattern[p_idx] == ']':
        char_set.add(']')
        last_added = ']'
        p_idx += 1

    while p_idx < len(pattern):
        if pattern[p_idx] == ']':
            break
        elif pattern[p_idx] == '-' and last_added is not None and p_idx + 1 < len(pattern) and pattern[p_idx + 1] != ']':
            end_char = pattern[p_idx + 1]
            start_char = last_added

            if ord(end_char) < ord(start_char):
                raise ValueError("Invalid range")

            char_set.discard(start_char)
            for i in range(ord(start_char), ord(end_char) + 1):
                char_set.add(chr(i))

            last_added = end_char
            p_idx += 2
        else:
            char_set.add(pattern[p_idx])
            last_added = pattern[p_idx]
            p_idx += 1

    if p_idx >= len(pattern):
        raise ValueError("Unclosed character class")

    p_idx += 1

    return p_idx, negate, char_set
